def call_key(row: Dict[str, Any]) -> CallKey:
    """The identity of a call. ``int()`` also turns the numpy integers of a parquet round trip
    into Python ones, which psycopg2 can adapt."""
    return int(row["ref_call_id"]), _destination(row.get("destination"))

def stored_call_keys(
    ref_call_ids: Sequence[int],
    fetch_records: Callable[[str, List[int]], Sequence[Sequence[Any]]],
) -> Set[CallKey]:
    """The identities, among ``ref_call_ids``, that are already in the table."""
    ids = sorted({int(i) for i in ref_call_ids})
    if not ids:
        return set()
    query = STORED_CALLS_SQL.format(placeholders=",".join(["%s"] * len(ids)))
    return {(int(record[0]), _destination(record[1])) for record in fetch_records(query, ids)}

def drop_stored_calls(
    rows: Sequence[Dict[str, Any]],
    fetch_records: Callable[[str, List[int]], Sequence[Sequence[Any]]],
) -> List[Dict[str, Any]]:
    """Rows whose call is not stored yet. A stored call with the same id but another
    destination does not hide the row."""
    if not rows:
        return []
    stored = stored_call_keys([int(row["ref_call_id"]) for row in rows], fetch_records)
    return [row for row in rows if call_key(row) not in stored]

def object_path(name: str) -> str:
    if name not in ALLOWED_NAMES:
        raise ValueError(f"dashboard desconhecido: {name!r}; validos: {ALLOWED_NAMES}")
    return f"{OBJECT_PREFIX}/{name}.json"

